def GetRecentActivitySummary(budget_id, days=None, account_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0379000" if __import__("os").path.isdir("./environment_mix/0379000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "GetRecentActivitySummary"
    used_cred = None
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _log(status, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": used_cred,
            "status": status,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(budget_id, str) or not re.match(r"^ynab_bdg_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        e = _err("VALIDATION_ERROR", "budget_id is missing or invalid", field="budget_id")
        _log("error", e["error"])
        return e

    if days is None:
        days_val = 30
    else:
        if not isinstance(days, int):
            e = _err("VALIDATION_ERROR", "days must be an integer", field="days")
            _log("error", e["error"])
            return e
        if days < 1 or days > 365:
            e = _err("VALIDATION_ERROR", "days must be between 1 and 365", field="days")
            _log("error", e["error"])
            return e
        days_val = days

    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^ynab_act_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
            e = _err("VALIDATION_ERROR", "account_id is invalid", field="account_id")
            _log("error", e["error"])
            return e

    users = _load("users.json")
    budgets = _load("budgets.json")
    accounts = _load("accounts.json")
    txns = _load("transactions.json")
    ents = _load("budget_entities.json")
    if not isinstance(users, list): users = []
    if not isinstance(budgets, list): budgets = []
    if not isinstance(accounts, list): accounts = []
    if not isinstance(txns, list): txns = []
    if not isinstance(ents, list): ents = []

    b = next((r for r in budgets if isinstance(r, dict) and r.get("id") == budget_id), None)
    if not b:
        e = _err("NOT_FOUND", "Budget not found", budget_id=budget_id)
        _log("error", e["error"])
        return e

    active_user = next((r for r in users if isinstance(r, dict) and r.get("status") == "active"), None)
    if not active_user or b.get("user_id") != active_user.get("id"):
        e = _err("UNAUTHORIZED", "Not allowed to access this budget", budget_id=budget_id)
        _log("error", e["error"])
        return e

    acct = None
    if account_id is not None:
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id and a.get("budget_id") == budget_id), None)
        if not acct:
            e = _err("NOT_FOUND", "Account not found in budget", account_id=account_id, budget_id=budget_id)
            _log("error", e["error"])
            return e

    # Window
    start_dt = (now_dt - datetime.timedelta(days=days_val)).replace(hour=0, minute=0, second=0, microsecond=0)
    start_iso = start_dt.isoformat()

    # Payee id->name
    payee_name = {}
    for e in ents:
        if isinstance(e, dict) and e.get("budget_id") == budget_id and e.get("entity_type") == "payee":
            if e.get("id"):
                payee_name[e["id"]] = e.get("name")

    inflow = 0
    outflow = 0
    cleared_counts = {"cleared": 0, "uncleared": 0, "reconciled": 0, "other": 0}
    payee_outflows = {}

    for t in txns:
        if not isinstance(t, dict):
            continue
        if t.get("budget_id") != budget_id:
            continue
        if t.get("status") != "active":
            continue
        if account_id is not None and t.get("account_id") != account_id:
            continue
        d = t.get("date")
        if not isinstance(d, str):
            continue
        # ISO compare works for isoformat with timezone; if stored as plain date, still ok lexicographically mostly.
        # Be strict-ish: parse.
        try:
            dt = datetime.datetime.fromisoformat(d.replace("Z", "+00:00")) if "T" in d else datetime.datetime.fromisoformat(d + "T00:00:00+00:00")
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            continue
        if dt < start_dt:
            continue

        amt = t.get("amount_milliunits")
        if not isinstance(amt, int):
            continue
        if amt > 0:
            inflow += amt
        elif amt < 0:
            outflow += (-amt)

        c = t.get("cleared")
        if c in ("cleared", "uncleared", "reconciled"):
            cleared_counts[c] += 1
        else:
            cleared_counts["other"] += 1

        if amt < 0:
            pid = t.get("payee_entity_id")
            key = pid if isinstance(pid, str) and pid else None
            if key:
                payee_outflows[key] = payee_outflows.get(key, 0) + (-amt)
            else:
                payee_outflows[None] = payee_outflows.get(None, 0) + (-amt)

    top = sorted(payee_outflows.items(), key=lambda kv: kv[1], reverse=True)[:5]
    top_payees = []
    for pid, total_abs_outflow in top:
        top_payees.append({
            "payee_entity_id": pid,
            "payee_name": payee_name.get(pid) if pid else None,
            "abs_outflow_milliunits": total_abs_outflow
        })

    resp = {
        "budget_id": budget_id,
        "account_id": account_id,
        "days": days_val,
        "window_start": start_iso,
        "window_end": now,
        "total_inflow_milliunits": inflow,
        "total_outflow_milliunits": outflow,
        "net_milliunits": inflow - outflow,
        "top_payees_by_abs_outflow": top_payees,
        "counts_by_cleared_state": cleared_counts
    }
    _log("ok")
    return resp

def GetBudgetMonths(budget_id, start_month=None, end_month=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0379000" if __import__("os").path.isdir("./environment_mix/0379000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    endpoint = "GetBudgetMonths"
    used_cred = None
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": used_cred,
            "status": status,
            "latency_ms": int((time.time() - start_t) * 1000),
            "timestamp": now
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(budget_id, str) or not re.match(r"^ynab_bdg_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        e = _err("VALIDATION_ERROR", "budget_id is missing or invalid", field="budget_id")
        _log("error", e["error"])
        return e

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a date string")
        try:
            d = datetime.date.fromisoformat(s)
        except Exception:
            raise ValueError(f"{field} is malformed; expected YYYY-MM-DD")
        return d

    try:
        sm = _parse_date(start_month, "start_month")
        em = _parse_date(end_month, "end_month")
    except ValueError as ve:
        e = _err("VALIDATION_ERROR", str(ve))
        _log("error", e["error"])
        return e

    if sm and em and sm > em:
        e = _err("VALIDATION_ERROR", "start_month must be on or before end_month", field="start_month")
        _log("error", e["error"])
        return e

    if limit is None:
        lim = 50
    else:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
            _log("error", e["error"])
            return e
        if limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit out of range (1-200)", field="limit")
            _log("error", e["error"])
            return e
        lim = limit

    if sort is None:
        sort_val = "month"
    else:
        if not isinstance(sort, str) or sort not in ("month", "-month"):
            e = _err("VALIDATION_ERROR", "sort must be one of: month, -month", field="sort")
            _log("error", e["error"])
            return e
        sort_val = sort

    # Cursor format: base64url(json {"budget_id":..., "offset": int, "sort":...})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            _log("error", e["error"])
            return e
        try:
            padded = cursor + ("=" * (-len(cursor) % 4))
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            _log("error", e["error"])
            return e
        if not isinstance(payload, dict) or payload.get("budget_id") != budget_id or payload.get("sort") != sort_val:
            e = _err("VALIDATION_ERROR", "cursor is invalid for this listing", field="cursor")
            _log("error", e["error"])
            return e
        off = payload.get("offset")
        if not isinstance(off, int) or off < 0:
            e = _err("VALIDATION_ERROR", "cursor offset is invalid", field="cursor")
            _log("error", e["error"])
            return e
        offset = off

    users = _load("users.json")
    budgets = _load("budgets.json")
    ents = _load("budget_entities.json")
    if not isinstance(users, list): users = []
    if not isinstance(budgets, list): budgets = []
    if not isinstance(ents, list): ents = []

    b = next((r for r in budgets if isinstance(r, dict) and r.get("id") == budget_id), None)
    if not b:
        e = _err("NOT_FOUND", "Budget not found", budget_id=budget_id)
        _log("error", e["error"])
        return e

    active_user = next((r for r in users if isinstance(r, dict) and r.get("status") == "active"), None)
    if not active_user or b.get("user_id") != active_user.get("id"):
        e = _err("UNAUTHORIZED", "Not allowed to access this budget", budget_id=budget_id)
        _log("error", e["error"])
        return e

    months = []
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("budget_id") != budget_id:
            continue
        if e.get("entity_type") != "month":
            continue
        if e.get("status") != "active":
            continue
        m = e.get("month")
        if not isinstance(m, str):
            continue
        # Compare by date
        try:
            d = datetime.date.fromisoformat(m.split("T")[0])
        except Exception:
            continue
        if sm and d < sm:
            continue
        if em and d > em:
            continue
        months.append(e)

    months.sort(key=lambda r: (r.get("month") or ""))
    if sort_val == "-month":
        months.reverse()

    total = len(months)
    page = months[offset: offset + lim]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        payload = {"budget_id": budget_id, "offset": next_offset, "sort": sort_val}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    resp = {
        "budget_id": budget_id,
        "months": page,
        "sort": sort_val,
        "limit": lim,
        "cursor": cursor,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor
    }
    _log("ok")
    return resp

def ListAccountTransactions(account_id, budget_id=None, since_date=None, until_date=None, cleared=None, approved=None, deleted=None, search=None, category_entity_id=None, payee_entity_id=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0379000" if __import__("os").path.isdir("./environment_mix/0379000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_date_ymd(s):
        try:
            dt = datetime.datetime.strptime(s, "%Y-%m-%d").date()
            return dt
        except Exception:
            return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            # allow trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _cursor_decode(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4)).decode("utf-8")
            return json.loads(raw)
        except Exception:
            return None

    def _cursor_encode(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{int((_t0%1)*1e9)}",
            "endpoint": "ListAccountTransactions",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate input types/patterns/enums/ranges
    if not isinstance(account_id, str) or not re.match(r"^ynab_act_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")

    if budget_id is not None:
        if not isinstance(budget_id, str) or not re.match(r"^ynab_bdg_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "budget_id is invalid.", field="budget_id")

    if since_date is not None:
        if not isinstance(since_date, str) or _parse_date_ymd(since_date) is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "since_date must be YYYY-MM-DD.", field="since_date")
    if until_date is not None:
        if not isinstance(until_date, str) or _parse_date_ymd(until_date) is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "until_date must be YYYY-MM-DD.", field="until_date")

    if since_date is not None and until_date is not None:
        sd = _parse_date_ymd(since_date)
        ud = _parse_date_ymd(until_date)
        if sd and ud and sd > ud:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "since_date must be <= until_date.", field="since_date")

    if cleared is not None:
        if not isinstance(cleared, str) or cleared not in ("cleared", "uncleared", "reconciled"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cleared is invalid.", field="cleared")

    if approved is not None and not isinstance(approved, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "approved must be boolean.", field="approved")

    if deleted is not None and not isinstance(deleted, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "deleted must be boolean.", field="deleted")

    if search is not None and not isinstance(search, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search must be a string.", field="search")

    if category_entity_id is not None:
        if not isinstance(category_entity_id, str) or not re.match(r"^ynab_ent_[0-9A-HJKMNP-TV-Z]{10,}$", category_entity_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "category_entity_id is invalid.", field="category_entity_id")

    if payee_entity_id is not None:
        if not isinstance(payee_entity_id, str) or not re.match(r"^ynab_ent_[0-9A-HJKMNP-TV-Z]{10,}$", payee_entity_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "payee_entity_id is invalid.", field="payee_entity_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")

    if sort is None:
        sort = "-date"
    if not isinstance(sort, str) or sort not in ("date", "-date", "amount_milliunits", "-amount_milliunits", "last_modified_on", "-last_modified_on"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")

    # Load data
    users = _load("users.json")
    budgets = _load("budgets.json")
    accounts = _load("accounts.json")
    entities = _load("budget_entities.json")
    txns = _load("transactions.json")

    # Ambient auth: find a combination that can serve (active user -> budget -> account)
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    acct_budget = next((b for b in budgets if b.get("id") == acct.get("budget_id")), None)
    if acct_budget is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Owning budget not found for account.", account_id=account_id)

    if budget_id is not None and acct_budget.get("id") != budget_id:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id does not belong to the provided budget_id.", field="budget_id")

    owner = next((u for u in users if u.get("id") == acct_budget.get("user_id")), None)
    if owner is None:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible user context for this account.")

    if owner.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is not active.")

    # Quota/limits prerequisite: budget must be active to serve listing (per rules "may require")
    if acct_budget.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Budget is not active.")

    # Validate entity filters belong to same budget and correct type when provided
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("budget_id") == acct_budget.get("id")}
    if category_entity_id is not None:
        e = ent_by_id.get(category_entity_id)
        if e is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Category entity not found in this budget.", category_entity_id=category_entity_id)
        if e.get("entity_type") != "category":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "category_entity_id must refer to a category entity.", field="category_entity_id")
    if payee_entity_id is not None:
        e = ent_by_id.get(payee_entity_id)
        if e is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Payee entity not found in this budget.", payee_entity_id=payee_entity_id)
        if e.get("entity_type") != "payee":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "payee_entity_id must refer to a payee entity.", field="payee_entity_id")

    # Cursor handling
    cur_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        cur_obj = _cursor_decode(cursor)
        if not isinstance(cur_obj, dict) or cur_obj.get("v") != 1 or cur_obj.get("endpoint") != "ListAccountTransactions":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid for this endpoint.", field="cursor")
        if cur_obj.get("account_id") != account_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor does not match account_id.", field="cursor")
        # lock filters to cursor
        for k in ("budget_id", "since_date", "until_date", "cleared", "approved", "deleted", "search", "category_entity_id", "payee_entity_id", "sort"):
            if cur_obj.get("filters", {}).get(k, None) != locals().get(k):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor does not match current filters.", field="cursor")
        if not isinstance(cur_obj.get("offset"), int) or cur_obj.get("offset") < 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor offset is invalid.", field="cursor")
        offset = cur_obj["offset"]
    else:
        offset = 0

    # Filter rows
    sd = _parse_date_ymd(since_date) if since_date is not None else None
    ud = _parse_date_ymd(until_date) if until_date is not None else None
    q = (search or "").strip().lower() if search is not None else None

    def _txn_date_key(t):
        d = _parse_dt(t.get("date"))
        return d if d is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    def _txn_updated_key(t):
        d = _parse_dt(t.get("updated_at"))
        return d if d is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    def _txn_lastmod_key(t):
        d = _parse_dt(t.get("last_modified_on"))
        return d if d is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows = []
    for t in txns:
        if not isinstance(t, dict):
            continue
        if t.get("budget_id") != acct_budget.get("id"):
            continue
        if t.get("account_id") != account_id:
            continue
        if t.get("status") != "active":
            continue
        if t.get("deleted") is True:
            # deleted transactions excluded by default and by status rule
            continue

        if deleted is not None:
            # for active rows deleted should be false, but keep filter semantics
            if bool(t.get("deleted")) != deleted:
                continue

        if cleared is not None and t.get("cleared") != cleared:
            continue
        if approved is not None and t.get("approved") is not None and t.get("approved") != approved:
            continue
        if approved is not None and t.get("approved") is None:
            # if unknown, doesn't match explicit filter
            continue

        if category_entity_id is not None and t.get("category_entity_id") != category_entity_id:
            continue
        if payee_entity_id is not None and t.get("payee_entity_id") != payee_entity_id:
            continue

        if sd is not None or ud is not None:
            ddt = _parse_dt(t.get("date"))
            if ddt is None:
                continue
            d = ddt.date()
            if sd is not None and d < sd:
                continue
            if ud is not None and d > ud:
                continue

        if q is not None and q != "":
            st = (t.get("search_text") or "")
            if not isinstance(st, str) or q not in st.lower():
                continue

        rows.append(t)

    # Sort
    reverse = sort.startswith("-")
    sk = sort[1:] if reverse else sort

    if sk == "date":
        rows.sort(key=lambda t: (_txn_date_key(t), _txn_updated_key(t)), reverse=reverse)
    elif sk == "amount_milliunits":
        rows.sort(key=lambda t: (t.get("amount_milliunits") if isinstance(t.get("amount_milliunits"), int) else 0, _txn_date_key(t), _txn_updated_key(t)), reverse=reverse)
    elif sk == "last_modified_on":
        rows.sort(key=lambda t: (_txn_lastmod_key(t), _txn_updated_key(t)), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        next_cursor = _cursor_encode({
            "v": 1,
            "endpoint": "ListAccountTransactions",
            "account_id": account_id,
            "filters": {
                "budget_id": budget_id,
                "since_date": since_date,
                "until_date": until_date,
                "cleared": cleared,
                "approved": approved,
                "deleted": deleted,
                "search": search,
                "category_entity_id": category_entity_id,
                "payee_entity_id": payee_entity_id,
                "sort": sort,
            },
            "offset": offset + limit
        })

    _log("ok")
    return {
        "data": {
            "transactions": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
