        cnt = 0
        for r in reversed(logs[-2000:]):
            if not isinstance(r, dict): 
                continue
            if r.get("endpoint") != "ListCategories":
                continue
            ts = r.get("timestamp")
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for ListCategories.")
