        return (v is None, v, r.get("id"))

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # cursor format: "v1:<budget_id>:<sort>:<order>:<offset>"
    offset = 0
    if cursor:
        parts = cursor.split(":")
        if len(parts) != 5 or parts[0] != "v1":
