        if parts[1] != budget_id or parts[2] != sort or parts[3] != order:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor does not match the current query.", field="cursor")
        try:
            offset = int(parts[4])
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor offset is invalid.", field="cursor")
        if offset < 0 or offset > len(rows):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor offset out of range.", field="cursor")

    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(rows)
    next_cursor = f"v1:{budget_id}:{sort}:{order}:{next_offset}" if has_more else None

    resp = {
