            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-2000:]):
            if not isinstance(r, dict): 
                continue
            if r.get("endpoint") != "GetCurrentMonthSnapshot":
                continue
            ts = r.get("timestamp")
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for GetCurrentMonthSnapshot.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT")
        return rl

    if not isinstance(budget_id, str) or not re.match(r"^ynab_bdg_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "budget_id is invalid.", field="budget_id")

    if include_hidden is not None and not isinstance(include_hidden, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_hidden must be boolean.", field="include_hidden")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "use_cache must be boolean.", field="use_cache")

    # Parse month (YYYY-MM-01) or default to current month start
    if month is None:
        month_dt = datetime.datetime(now_dt.year, now_dt.month, 1, tzinfo=datetime.timezone.utc)
        month_str = month_dt.date().isoformat()
    else:
        if not isinstance(month, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "month must be a date string (YYYY-MM-01).", field="month")
        try:
            d = datetime.date.fromisoformat(month)
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "month is not a valid date (expected YYYY-MM-01).", field="month")
        if d.day != 1:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "month must be anchored to the first of the month (YYYY-MM-01).", field="month")
        month_dt = datetime.datetime(d.year, d.month, 1, tzinfo=datetime.timezone.utc)
        month_str = d.isoformat()

    # --- auth resolution (ambient) ---
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    active_users = [u for u in users if isinstance(u, dict) and u.get("status") == "active"]
    if not active_users:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active user context available.")

    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []

    budget = None
    for u in active_users:
        for b in budgets:
            if not isinstance(b, dict):
                continue
            if b.get("id") == budget_id and b.get("user_id") == u.get("id"):
                budget = b
                break
        if budget:
            break

    if not budget:
        exists = any(isinstance(b, dict) and b.get("id") == budget_id for b in budgets)
        if exists:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Not authorized for this budget.")
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Budget not found.", budget_id=budget_id)

    if budget.get("status") != "active":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Budget is not active.")

    entities = _load("budget_entities.json")
    if not isinstance(entities, list):
        entities = []
    txns = _load("transactions.json")
    if not isinstance(txns, list):
        txns = []

    # Identify month row (entity_type=month, ynab_entity_id as normalized month key could be month_str)
    month_row = None
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("budget_id") != budget_id:
            continue
        if e.get("entity_type") != "month":
            continue
        if e.get("status") != "active":
            continue
        # match either month field or ynab_entity_id
        if e.get("month"):
            try:
                mdt = datetime.datetime.fromisoformat(str(e.get("month")).replace("Z", "+00:00"))
                if mdt.date().isoformat() == month_str:
                    month_row = e
                    break
            except Exception:
                pass
        if e.get("ynab_entity_id") == month_str:
            month_row = e
            break

    # categories in budget
    categories = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("budget_id") != budget_id or e.get("entity_type") != "category":
            continue
        if e.get("status") != "active":
            continue
        if not include_hidden and e.get("hidden") is True:
            continue
        categories.append(e)

    # If cache allowed and present on month_row, return it with minimal compute.
    cached_ok = False
    snapshot_totals = None
    if use_cache and month_row:
        # consider cache present when all three fields exist (could be 0) AND not None
        bm = month_row.get("budgeted_milliunits")
        am = month_row.get("activity_milliunits")
        tbb = month_row.get("to_be_budgeted_milliunits")
        if bm is not None and am is not None and tbb is not None:
            cached_ok = True
            snapshot_totals = {"budgeted_milliunits": bm, "activity_milliunits": am, "to_be_budgeted_milliunits": tbb}

    # Compute aggregates when cache is missing or disallowed.
    # Month window: [month_start, next_month_start)
    next_month = (month_dt.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
    # category activity: sum amounts for txns in month, by category_entity_id
    cat_activity = {}
    total_activity = 0
    for t in txns:
        if not isinstance(t, dict):
            continue
        if t.get("budget_id") != budget_id:
            continue
        if t.get("status") != "active":
            continue
        # parse date
        td = t.get("date")
        if not td:
            continue
        try:
            tdt = datetime.datetime.fromisoformat(str(td).replace("Z", "+00:00"))
        except Exception:
            continue
        if not (month_dt <= tdt.replace(tzinfo=tdt.tzinfo or datetime.timezone.utc) < next_month):
            continue
        amt = t.get("amount_milliunits")
        if not isinstance(amt, int):
            continue
        total_activity += amt
        cid = t.get("category_entity_id")
        if cid:
            cat_activity[cid] = cat_activity.get(cid, 0) + amt

    if snapshot_totals is None:
        # we cannot derive true "budgeted" or "TBB" from available mirror tables; use month_row if present else null
        bm = month_row.get("budgeted_milliunits") if month_row else None
        tbb = month_row.get("to_be_budgeted_milliunits") if month_row else None
        snapshot_totals = {
            "budgeted_milliunits": bm,
            "activity_milliunits": total_activity,
            "to_be_budgeted_milliunits": tbb
        }

    cat_rows = []
    # map entity id -> name for category rows
    for c in categories:
        cid = c.get("id")
        cat_rows.append({
            "category_entity_id": cid,
            "ynab_entity_id": c.get("ynab_entity_id"),
            "name": c.get("name"),
            "hidden": c.get("hidden"),
            "activity_milliunits": cat_activity.get(cid, 0),
            "budgeted_milliunits": c.get("budgeted_milliunits"),
            "note": c.get("note"),
            "last_modified_on": c.get("last_modified_on"),
            "updated_at": c.get("updated_at")
        })

    # stable ordering by name asc
    cat_rows.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("ynab_entity_id") or "", r.get("category_entity_id") or ""))

    resp = {
        "data": {
            "budget_id": budget_id,
            "month": month_str,
            "month_entity": month_row,
            "totals": snapshot_totals,
            "categories": cat_rows,
            "cache": {"used": bool(cached_ok), "eligible": bool(use_cache)}
        }
    }
    _log("OK", extra={"categories": len(cat_rows), "cached": bool(cached_ok)})
    return resp

