    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        rnd = uuid.uuid4().int
        out = []
        for _ in range(16):
            out.append(alphabet[rnd % 32])
            rnd //= 32
        return f"{prefix}_{''.join(out)}"

    def _parse_dt_any(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip()
        if not s2:
            return None
        # Accept "YYYY-MM-DD" (tool schema) and also ISO timestamps "YYYY-MM-DDTHH:MM:SSZ"
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", s2):
            try:
                d = datetime.date.fromisoformat(s2)
                return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        # ISO datetime
        try:
            dt = datetime.datetime.fromisoformat(s2.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            # Normalize to UTC midnight for inclusive date-window comparisons
            return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _log(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "GetIncomeVsExpenseSummary",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # Simple per-endpoint rolling window limiter based on request_logs
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "GetIncomeVsExpenseSummary":
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
                if cnt >= 120:
                    return _err("RATE_LIMIT", "Rate limit exceeded for GetIncomeVsExpenseSummary.")
            else:
                break
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT")
        return rl

    # --- Validate inputs (relaxed to accept actual observed args while respecting schema intent) ---
    if not isinstance(budget_id, str) or not re.match(r"^ynab_bdg_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "budget_id is invalid.", field="budget_id")

    sd = _parse_dt_any(start_date)
    if sd is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_date is invalid (expected YYYY-MM-DD or an ISO-8601 timestamp).", field="start_date")

    ed = _parse_dt_any(end_date)
    if ed is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_date is invalid (expected YYYY-MM-DD or an ISO-8601 timestamp).", field="end_date")

    if sd > ed:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_date must be on or before end_date.", field="start_date")

    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^ynab_act_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")

    if include_transfers is not None and not isinstance(include_transfers, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_transfers must be a boolean.", field="include_transfers")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.", field="include_deleted")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.", field="use_cache")

    include_transfers = bool(include_transfers) if include_transfers is not None else False
    include_deleted = bool(include_deleted) if include_deleted is not None else False
    use_cache = bool(use_cache) if use_cache is not None else False

    # --- Resolve an authorized context (ambient auth) ---
    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []
    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    budget = None
    for b in budgets:
        if isinstance(b, dict) and b.get("id") == budget_id:
            budget = b
            break
    if budget is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "budget_id not found.", field="budget_id")

    user = None
    uid = budget.get("user_id")
    for u in users:
        if isinstance(u, dict) and u.get("id") == uid:
            user = u
            break
    if user is None:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized user context could be resolved for this budget.")

    # Serve only for active user (per quota/limits rule: may require active)
    if user.get("status") != "active":
        _log("UNAUTHORIZED", credential_id=user.get("id"), meta={"reason": "user_not_active"})
        return _err("UNAUTHORIZED", "User is not active for this operation.")

    # Budget should generally be active for reporting; allow if not archived? We'll require not archived.
    if budget.get("status") == "archived":
        _log("UNAUTHORIZED", credential_id=user.get("id"), meta={"reason": "budget_archived"})
        return _err("UNAUTHORIZED", "Budget is archived and cannot be summarized.")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    if account_id is not None:
        acc = None
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                acc = a
                break
        if acc is None:
            _log("NOT_FOUND", credential_id=user.get("id"))
            return _err("NOT_FOUND", "account_id not found.", field="account_id")
        if acc.get("budget_id") != budget_id:
            _log("VALIDATION_ERROR", credential_id=user.get("id"))
            return _err("VALIDATION_ERROR", "account_id does not belong to budget_id.", field="account_id")

    # --- Compute summary over mirrored transactions ---
    txs = _load("transactions.json")
    if not isinstance(txs, list):
        txs = []

    income = 0
    expense_abs = 0
    matched = 0

    for t in txs:
        if not isinstance(t, dict):
            continue
        if t.get("budget_id") != budget_id:
            continue
        if account_id is not None and t.get("account_id") != account_id:
            continue

        status = t.get("status")
        if not include_deleted:
            if status != "active":
                continue
        else:
            if status not in ("active", "deleted"):
                continue

        if not include_transfers and t.get("transfer_account_id") is not None:
            continue

        dt = _parse_dt_any(t.get("date"))
        if dt is None:
            continue
        if dt < sd or dt > ed:
            continue

        amt = t.get("amount_milliunits")
        if not isinstance(amt, int):
            continue

        matched += 1
        if amt > 0:
            income += amt
        elif amt < 0:
            expense_abs += -amt

    resp = {
        "data": {
            "budget_id": budget_id,
            "account_id": account_id,
            "start_date": sd.date().isoformat(),
            "end_date": ed.date().isoformat(),
            "include_transfers": include_transfers,
            "include_deleted": include_deleted,
            "income_milliunits": income,
            "expense_milliunits": expense_abs,
            "net_milliunits": income - expense_abs,
            "transaction_count": matched,
            "generated_at": now_iso,
            "cached": False
        }
    }
    _log("OK", credential_id=user.get("id"), meta={"matched": matched})
    return resp

def SearchTransactions(budget_id, query=None, account_id=None, payee_entity_id=None, category_entity_id=None, cleared=None, approved=None, flag_color=None, min_amount_milliunits=None, max_amount_milliunits=None, start_date=None, end_date=None, include_deleted=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0379000" if __import__("os").path.isdir("./environment_mix/0379000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # ---- request logging + quota/rate-limits (best-effort; stored in request_log.json) ----
    def _get_cred_from_ambient():
        # No explicit credential in this endpoint; choose an active user with at least one active budget.
        users = _load("users.json")
        budgets = _load("budgets.json")
        for u in users:
            if u.get("status") == "active":
                if any(b.get("user_id") == u.get("id") and b.get("status") == "active" for b in budgets):
                    return {"type": "user", "id": u.get("id")}
        # fallback: any active user at all
        for u in users:
            if u.get("status") == "active":
                return {"type": "user", "id": u.get("id")}
        return None

    def _check_limits(cred_key, endpoint):
        # Sliding-window rate: 60/min; daily quota: 2000/day for search/list endpoints
        logs = _load("request_log.json")
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        win_start = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("credential") != cred_key or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
            except Exception:
                ts_dt = None
            if not ts_dt:
                continue
            if ts_dt >= win_start:
                per_min += 1
            if ts_dt >= day_start:
                per_day += 1

        if per_min >= 60:
            reset = (win_start + datetime.timedelta(seconds=60)).isoformat()
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=60, window_seconds=60, reset_at=reset)
        if per_day >= 2000:
            reset = (day_start + datetime.timedelta(days=1)).isoformat()
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=2000, period="day", reset_at=reset)
        return None

    def _log(endpoint, cred_key, status, latency_ms, meta=None):
        logs = _load("request_log.json")
        row = {
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=").lower(),
            "endpoint": endpoint,
            "credential": cred_key,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_log.json", logs)

    endpoint = "SearchTransactions"
    cred = _get_cred_from_ambient()
    cred_key = cred["type"] + ":" + cred["id"] if cred else "anonymous"
    limit_check = _check_limits(cred_key, endpoint)
    if limit_check:
        _log(endpoint, cred_key, limit_check["error"]["code"], (time.time() - t0) * 1000, meta={"budget_id": budget_id})
        return limit_check

    # ---- validation ----
    if not isinstance(budget_id, str) or not re.match(r"^ynab_bdg_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        e = _err("VALIDATION_ERROR", "budget_id is invalid", field="budget_id")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    def _pat(val, pat, field):
        if val is None:
            return None
        if not isinstance(val, str) or not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"{field} is invalid", field=field)
        return None

    for v, p, f in [
        (account_id, r"^ynab_act_[0-9A-HJKMNP-TV-Z]{10,}$", "account_id"),
        (payee_entity_id, r"^ynab_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "payee_entity_id"),
        (category_entity_id, r"^ynab_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "category_entity_id"),
    ]:
        err = _pat(v, p, f)
        if err:
            _log(endpoint, cred_key, err["error"]["code"], (time.time() - t0) * 1000)
            return err

    if query is not None and not isinstance(query, str):
        e = _err("VALIDATION_ERROR", "query must be a string", field="query")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if cleared is not None:
        if not isinstance(cleared, str) or cleared not in ("cleared", "uncleared", "reconciled"):
            e = _err("VALIDATION_ERROR", "cleared is invalid", field="cleared")
            _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
            return e

    if approved is not None and not isinstance(approved, bool):
        e = _err("VALIDATION_ERROR", "approved must be boolean", field="approved")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if include_deleted is not None and not isinstance(include_deleted, bool):
        e = _err("VALIDATION_ERROR", "include_deleted must be boolean", field="include_deleted")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if flag_color is not None and not isinstance(flag_color, str):
        e = _err("VALIDATION_ERROR", "flag_color must be a string", field="flag_color")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if min_amount_milliunits is not None and not isinstance(min_amount_milliunits, int):
        e = _err("VALIDATION_ERROR", "min_amount_milliunits must be integer", field="min_amount_milliunits")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e
    if max_amount_milliunits is not None and not isinstance(max_amount_milliunits, int):
        e = _err("VALIDATION_ERROR", "max_amount_milliunits must be integer", field="max_amount_milliunits")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e
    if min_amount_milliunits is not None and max_amount_milliunits is not None and min_amount_milliunits > max_amount_milliunits:
        e = _err("VALIDATION_ERROR", "min_amount_milliunits cannot exceed max_amount_milliunits", field="min_amount_milliunits")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    def _parse_date(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date string (YYYY-MM-DD)", field=field)
        try:
            d = datetime.date.fromisoformat(s)
            dt = datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format", field=field)

    start_dt, err = _parse_date(start_date, "start_date")
    if err:
        _log(endpoint, cred_key, err["error"]["code"], (time.time() - t0) * 1000)
        return err
    end_dt, err = _parse_date(end_date, "end_date")
    if err:
        _log(endpoint, cred_key, err["error"]["code"], (time.time() - t0) * 1000)
        return err
    if start_dt and end_dt and start_dt > end_dt:
        e = _err("VALIDATION_ERROR", "start_date cannot be after end_date", field="start_date")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if sort is None:
        sort = "date"
    if not isinstance(sort, str) or sort not in ("date", "amount_milliunits", "last_modified_on", "created_at"):
        e = _err("VALIDATION_ERROR", "sort is invalid", field="sort")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order is invalid", field="order")
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
        return e

    # ---- auth/context resolution: require active user and active budget for serving results ----
    users = _load("users.json")
    budgets = _load("budgets.json")
    txs = _load("transactions.json")
    accounts = _load("accounts.json")
    entities = _load("budget_entities.json")

    # budget must exist and be active, and its user must be active
    bud = next((b for b in budgets if b.get("id") == budget_id), None)
    if not bud:
        e = _err("NOT_FOUND", "Budget not found", budget_id=budget_id)
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000, meta={"budget_id": budget_id})
        return e
    if bud.get("status") != "active":
        e = _err("UNAUTHORIZED", "Budget is not active for search operations", budget_id=budget_id)
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000, meta={"budget_id": budget_id, "status": bud.get("status")})
        return e
    user = next((u for u in users if u.get("id") == bud.get("user_id")), None)
    if not user or user.get("status") != "active":
        e = _err("UNAUTHORIZED", "User is not active", user_id=bud.get("user_id"))
        _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000, meta={"budget_id": budget_id})
        return e

    # validate referenced ids belong to this budget when provided
    if account_id is not None:
        arow = next((a for a in accounts if a.get("id") == account_id), None)
        if not arow:
            e = _err("NOT_FOUND", "Account not found", account_id=account_id)
            _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
            return e
        if arow.get("budget_id") != budget_id:
            e = _err("CONFLICT", "account_id does not belong to budget_id", account_id=account_id, budget_id=budget_id)
            _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
            return e

    def _validate_entity(eid, expected_type, field):
        if eid is None:
            return None
        erow = next((e for e in entities if e.get("id") == eid), None)
        if not erow:
            return _err("NOT_FOUND", f"{field} not found", **{field: eid})
        if erow.get("budget_id") != budget_id:
            return _err("CONFLICT", f"{field} does not belong to budget_id", **{field: eid, "budget_id": budget_id})
        if erow.get("entity_type") != expected_type:
            return _err("CONFLICT", f"{field} is not a {expected_type} entity", **{field: eid})
        return None

    err = _validate_entity(payee_entity_id, "payee", "payee_entity_id")
    if err:
        _log(endpoint, cred_key, err["error"]["code"], (time.time() - t0) * 1000)
        return err
    err = _validate_entity(category_entity_id, "category", "category_entity_id")
    if err:
        _log(endpoint, cred_key, err["error"]["code"], (time.time() - t0) * 1000)
        return err

    # ---- filter ----
    q = (query or "").strip().lower()
    inc_del = bool(include_deleted) if include_deleted is not None else False

    filtered = []
    for tr in txs:
        if tr.get("budget_id") != budget_id:
            continue
        if inc_del:
            if tr.get("status") not in ("active", "deleted"):
                continue
        else:
            if tr.get("status") != "active":
                continue
            if tr.get("deleted") is True:
                continue

        if account_id is not None and tr.get("account_id") != account_id:
            continue
        if payee_entity_id is not None and tr.get("payee_entity_id") != payee_entity_id:
            continue
        if category_entity_id is not None and tr.get("category_entity_id") != category_entity_id:
            continue
        if cleared is not None and tr.get("cleared") != cleared:
            continue
        if approved is not None and tr.get("approved") != approved:
            continue
        if flag_color is not None and tr.get("flag_color") != flag_color:
            continue
        amt = tr.get("amount_milliunits")
        if min_amount_milliunits is not None and isinstance(amt, int) and amt < min_amount_milliunits:
            continue
        if max_amount_milliunits is not None and isinstance(amt, int) and amt > max_amount_milliunits:
            continue

        # date filter expects UTC midnight ISO-ish; compare by date
        if start_dt is not None or end_dt is not None:
            dval = tr.get("date")
            dtv = None
            if isinstance(dval, str):
                try:
                    dtv = datetime.datetime.fromisoformat(dval.replace("Z", "+00:00"))
                except Exception:
                    dtv = None
            if not dtv:
                continue
            if start_dt is not None and dtv < start_dt:
                continue
            if end_dt is not None and dtv > (end_dt + datetime.timedelta(days=1) - datetime.timedelta(microseconds=1)):
                # inclusive end date
                continue

        if q:
            st = tr.get("search_text")
            if not isinstance(st, str) or q not in st.lower():
                continue

        filtered.append(tr)

    # ---- sorting ----
    def _dt_key(v):
        if not isinstance(v, str) or not v:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    reverse = (order == "desc")

    if sort == "date":
        filtered.sort(key=lambda r: (_dt_key(r.get("date")), _dt_key(r.get("updated_at"))), reverse=reverse)
    elif sort == "amount_milliunits":
        filtered.sort(key=lambda r: (r.get("amount_milliunits") if isinstance(r.get("amount_milliunits"), int) else 0, _dt_key(r.get("updated_at"))), reverse=reverse)
    elif sort == "last_modified_on":
        filtered.sort(key=lambda r: (_dt_key(r.get("last_modified_on")), _dt_key(r.get("updated_at"))), reverse=reverse)
    elif sort == "created_at":
        filtered.sort(key=lambda r: (_dt_key(r.get("created_at")), _dt_key(r.get("updated_at"))), reverse=reverse)

    # ---- cursor pagination ----
    # cursor encodes an integer offset and a stable digest of (budget_id, sort, order, query) to prevent misuse
    def _cursor_sig():
        h = hashlib.sha256()
        h.update((budget_id + "|" + sort + "|" + order + "|" + q).encode("utf-8"))
        return base64.urlsafe_b64encode(h.digest()[:12]).decode("ascii").rstrip("=")

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor + "==").decode("utf-8")
            parts = raw.split(":")
            if len(parts) != 2:
                raise ValueError("bad cursor")
            sig, off_s = parts
            if sig != _cursor_sig():
                e = _err("VALIDATION_ERROR", "cursor does not match query context", field="cursor")
                _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
                return e
            offset = int(off_s)
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            _log(endpoint, cred_key, e["error"]["code"], (time.time() - t0) * 1000)
            return e

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"{_cursor_sig()}:{next_offset}".encode("utf-8")).decode("ascii").rstrip("=")

    resp = {
        "data": {
            "transactions": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "has_more": has_more,
                "next_cursor": next_cursor
            },
            "sort": {"field": sort, "order": order},
            "as_of": now
        }
    }

    _log(endpoint, cred_key, "OK", (time.time() - t0) * 1000, meta={"budget_id": budget_id, "returned": len(page), "total": total})
    return resp

def WhoAmI(authorization, include_quota=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0379000" if __import__("os").path.isdir("./environment_mix/0379000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(endpoint, cred_key, status, latency_ms, meta=None):
        logs = _load("request_log.json")
        row = {
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=").lower(),
            "endpoint": endpoint,
            "credential": cred_key,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_log.json", logs)

    endpoint = "WhoAmI"

    if not isinstance(authorization, str) or not authorization.strip():
        e = _err("VALIDATION_ERROR", "authorization is required", field="authorization")
        _log(endpoint, "anonymous", e["error"]["code"], (time.time() - t0) * 1000)
        return e

    if include_quota is not None and not isinstance(include_quota, bool):
        e = _err("VALIDATION_ERROR", "include_quota must be boolean", field="include_quota")
        _log(endpoint, "anonymous", e["error"]["code"], (time.time() - t0) * 1000)
        return e

    # Accept either "Bearer <token>" or raw token; resolve against users.id or users.ynab_access_token_ciphertext
    m = re.match(r"^\s*Bearer\s+(.+?)\s*$", authorization, re.IGNORECASE)
    tok = (m.group(1) if m else authorization).strip()

    users = _load("users.json")

    resolved = None
    # Prefer active user
    for u in users:
        if u.get("status") == "active" and (u.get("id") == tok or u.get("ynab_access_token_ciphertext") == tok):
            resolved = u
            break
    if not resolved:
        for u in users:
            if u.get("id") == tok or u.get("ynab_access_token_ciphertext") == tok:
                resolved = u
                break

    if not resolved:
        e = _err("UNAUTHORIZED", "Invalid credential")
        _log(endpoint, "anonymous", e["error"]["code"], (time.time() - t0) * 1000)
        return e

    # Entitlement: must not be revoked
    if resolved.get("status") == "revoked":
        e = _err("UNAUTHORIZED", "Credential revoked", user_id=resolved.get("id"))
        _log(endpoint, "user:" + str(resolved.get("id")), e["error"]["code"], (time.time() - t0) * 1000)
        return e

    cred_key = "user:" + str(resolved.get("id"))

    data = {
        "data": {
            "subject": {
                "type": "user",
                "user_id": resolved.get("id"),
                "ynab_user_id": resolved.get("ynab_user_id"),
                "display_name": resolved.get("display_name"),
                "status": resolved.get("status")
            },
            "scopes": ["ynab:mirror:read", "ynab:mirror:write"],
        }
    }

    if include_quota:
        logs = _load("request_log.json")
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        win_start = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("credential") != cred_key:
                continue
            ts = r.get("timestamp")
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
            except Exception:
                ts_dt = None
            if not ts_dt:
                continue
            if ts_dt >= win_start:
                per_min += 1
            if ts_dt >= day_start:
                per_day += 1

        data["data"]["usage"] = {
            "rate_limit": {"limit": 60, "window_seconds": 60, "used": per_min, "remaining": max(0, 60 - per_min), "reset_at": (win_start + datetime.timedelta(seconds=60)).isoformat()},
            "quota": {"period": "day", "limit": 2000, "used": per_day, "remaining": max(0, 2000 - per_day), "reset_at": (day_start + datetime.timedelta(days=1)).isoformat()},
        }

    _log(endpoint, cred_key, "OK", (time.time() - t0) * 1000)
    return data

def SyncBudget(authorization, budget_id, sync_mode=None, force=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0379000" if __import__("os").path.isdir("./environment_mix/0379000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        rnd = uuid.uuid4().int
        out = []
        for _ in range(16):
            out.append(alphabet[rnd % 32])
            rnd //= 32
        return f"{prefix}_{''.join(out)}"

    def _log(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "SyncBudget",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "SyncBudget":
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
                if cnt >= 30:
                    return _err("RATE_LIMIT", "Rate limit exceeded for SyncBudget.")
            else:
                break
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT")
        return rl

    # --- Input validation (authorization is an identifier for a user in this datastore, not a strict Bearer format) ---
    if not isinstance(authorization, str) or not authorization.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "authorization must be a non-empty string.", field="authorization")

    if not isinstance(budget_id, str) or not re.match(r"^ynab_bdg_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "budget_id is invalid.", field="budget_id")

    if sync_mode is not None:
        if not isinstance(sync_mode, str) or sync_mode not in ("incremental", "full"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sync_mode must be one of: incremental, full.", field="sync_mode")
    else:
        sync_mode = "incremental"

    if force is not None and not isinstance(force, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "force must be a boolean.", field="force")
    force = bool(force) if force is not None else False

    # --- Authenticate/resolve context ---
    # authorization may be:
    #  - "Bearer <value>" (legacy)
    #  - a local users.id / ynab_user_id (as in audit args)
    auth_val = authorization.strip()
    if auth_val.lower().startswith("bearer "):
        auth_val = auth_val.split(None, 1)[1].strip()

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []

    budget = None
    for b in budgets:
        if isinstance(b, dict) and b.get("id") == budget_id:
            budget = b
            break
    if budget is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "budget_id not found.", field="budget_id")

    # Prefer user that matches both budget owner and authorization value; otherwise search for any workable combo.
    budget_user_id = budget.get("user_id")
    user = None
    for u in users:
        if not isinstance(u, dict):
            continue
        if u.get("id") != budget_user_id:
            continue
        if auth_val in (u.get("id"), u.get("ynab_user_id")):
            user = u
            break
    if user is None:
        # fall back: allow authorization to be omitted in practice but parameter is required;
        # if it doesn't match, still attempt budget owner as context only if active.
        for u in users:
            if isinstance(u, dict) and u.get("id") == budget_user_id:
                user = u
                break

    if user is None:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized user context could be resolved for this budget.")

    if user.get("status") != "active":
        _log("UNAUTHORIZED", credential_id=user.get("id"), meta={"reason": "user_not_active"})
        return _err("UNAUTHORIZED", "User is not active for this operation.")

    # Budget lifecycle constraints
    if budget.get("status") == "archived":
        _log("INVALID_TRANSITION", credential_id=user.get("id"))
        return _err("INVALID_TRANSITION", "Cannot sync an archived budget.")

    # Enforce budget ownership
    if budget.get("user_id") != user.get("id"):
        _log("UNAUTHORIZED", credential_id=user.get("id"))
        return _err("UNAUTHORIZED", "Authorization does not grant access to this budget.")

    # Any sync operation must set status to 'syncing' at start; reject invalid transition
    allowed_from = {
        "active": ("syncing", "archived", "sync_error"),
        "sync_error": ("syncing", "archived"),
        "syncing": ("active", "sync_error"),
        "archived": ()
    }
    cur_status = budget.get("status")
    if cur_status not in allowed_from:
        _log("INVALID_TRANSITION", credential_id=user.get("id"))
        return _err("INVALID_TRANSITION", f"Budget status '{cur_status}' is not a valid lifecycle state.")
    if "syncing" not in allowed_from.get(cur_status, ()):
        _log("INVALID_TRANSITION", credential_id=user.get("id"))
        return _err("INVALID_TRANSITION", f"Cannot transition budget from '{cur_status}' to 'syncing'.")

    # Optionally refuse too-frequent sync unless force=true (lightweight rule)
    if not force:
        last_sync_at = budget.get("last_sync_at")
        if isinstance(last_sync_at, str) and last_sync_at:
            try:
                last_dt = datetime.datetime.fromisoformat(last_sync_at.replace("Z", "+00:00"))
                if last_dt.tzinfo is None:
                    last_dt = last_dt.replace(tzinfo=datetime.timezone.utc)
                if (now_dt - last_dt) < datetime.timedelta(seconds=30):
                    _log("CONFLICT", credential_id=user.get("id"))
                    return _err("CONFLICT", "Budget was synced recently; retry later or use force=true.")
            except ValueError:
                pass

    # --- Persist: set syncing at start ---
    mutated = 0
    for i, b in enumerate(budgets):
        if isinstance(b, dict) and b.get("id") == budget_id:
            budgets[i] = dict(b)
            budgets[i]["status"] = "syncing"
            budgets[i]["updated_at"] = now_iso
            mutated = 1
            budget = budgets[i]
            break
    if mutated != 1:
        _log("NOT_FOUND", credential_id=user.get("id"))
        return _err("NOT_FOUND", "budget_id not found.", field="budget_id")

    _save("budgets.json", budgets)

    # --- "Sync" completion: since offline datastore, simulate a successful sync by advancing metadata only ---
    # Must transition atomically to active/sync_error; here we deterministically succeed.
    new_cursor = budget.get("last_sync_cursor")
    if sync_mode == "full":
        new_cursor = now_iso
    else:
        # incremental: always advance cursor; if none, set it
        new_cursor = now_iso

    for i, b in enumerate(budgets):
        if isinstance(b, dict) and b.get("id") == budget_id:
            budgets[i] = dict(b)
            # legal transition syncing -> active
            if "active" not in allowed_from.get("syncing", ()):
                _log("INVALID_TRANSITION", credential_id=user.get("id"))
                return _err("INVALID_TRANSITION", "Illegal lifecycle transition from syncing to active.")
            budgets[i]["status"] = "active"
            budgets[i]["last_sync_at"] = now_iso
            budgets[i]["last_sync_cursor"] = new_cursor
            budgets[i]["updated_at"] = now_iso
            budget = budgets[i]
            mutated = 1
            break
    if mutated != 1:
        _log("NOT_FOUND", credential_id=user.get("id"))
        return _err("NOT_FOUND", "budget_id not found during completion.", field="budget_id")

    _save("budgets.json", budgets)

    _log("OK", credential_id=user.get("id"), meta={"sync_mode": sync_mode, "force": force})
    return {
        "data": {
            "id": budget.get("id"),
            "user_id": budget.get("user_id"),
            "status": budget.get("status"),
            "last_sync_at": budget.get("last_sync_at"),
            "last_sync_cursor": budget.get("last_sync_cursor"),
            "updated_at": budget.get("updated_at"),
        }
    }
